  async function saveCuration(){
    const data=state.businessVariants,id=state.reviewingVariantId;
    if(!data||!id)return;
    try{await api('/api/business-briefs/'+encodeURIComponent(data.submissionId)+'/reviews','PUT',{branchId:id,status:$('#curation-status').value,note:$('#curation-note').value});await showBusinessVariants(data.submissionId);announce('Приватный редакционный статус сохранён.');}
    catch(e){announce(e.message,true);}
  }
  function exportBusinessVariants(){
    const data=state.businessVariants;if(!data)return;
    // Prevent spreadsheet formula injection in user-written text.
    const cell=value=>{let v=String(value??'');if(/^[\t\r\n =+@-]/.test(v)&&/^[\s]*[=+@-]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';};
    const fields=['id','parentId','generation','changedGene','hook','tone','cta','actionStatus','reviewStatus','reviewNote','createdAt'];
    const csv='\uFEFF'+[fields.map(cell).join(','),...data.variants.map(row=>fields.map(key=>cell(row[key])).join(','))].join('\r\n')+'\r\n';
    downloadText('protocol-zero-campaign-'+data.campaignId+'.csv',csv);
    announce('Экспортированы публичные варианты; личные черновики не включены.');
  }
